    for (const [k, v] of Object.entries(value)) out[k] = SECRET_KEY.test(k) ? '[REDACTED]' : redact(v, depth + 1);
    return out;
  }
  return value;
};

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);

return $input.all().map(({ json }) => {
  const execution = json.execution || {};
  const error = execution.error || (json.trigger && json.trigger.error) || {};
  const alert = {
    alertType: 'email_waterfall_execution_error',
    at: new Date().toISOString(),
    workflow: { id: json.workflow ? json.workflow.id : null, name: redactString(json.workflow ? json.workflow.name : '') },
    execution: { id: execution.id || null, mode: execution.mode || null, retryOf: execution.retryOf || null },
    lastNodeExecuted: execution.lastNodeExecuted || null,
    errorName: redactString(error.name || 'Error'),
    errorMessage: redactString(error.message || 'unknown error').slice(0, 300),
    nextStep: 'Open the execution in n8n (restricted access) and check the node named in lastNodeExecuted.',
  };
  try { console.error(`[email-waterfall:error] ${JSON.stringify(alert)}`); } catch (e) { /* best effort */ }
  const notify = !SANDBOX_MODE && !DRY_RUN && env('SLACK_WEBHOOK_URL', '') !== '' && flag('SLACK_NOTIFY_ON_MONITOR_ERROR', true);
  return {
    json: {
      ...alert,
      notify,
      slackMessage: {
        text: `Email verification waterfall failed at ${alert.lastNodeExecuted || 'unknown node'}`,
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: '⚠️ Email verification waterfall failed', emoji: true } },
          { type: 'section', text: { type: 'mrkdwn', text: `*Node:* ${alert.lastNodeExecuted || 'unknown'}\n*Error:* ${alert.errorName}: ${alert.errorMessage}` } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: `Execution \`${alert.execution.id || 'n/a'}\` · claimed queue rows return to pending after 30 minutes and are retried` }] },
        ],
      },
    },
  };
});
